/* ── Full conference set for the gallery slider ─────────────
   lib/gallery-manifest.json is generated by scripts/optimize-images.mjs,
   so new photos dropped into public/assets/gallery/people appear here
   after re-running the script. */


export type GallerySlide = Photo & { day?: number };

const knownAlt = new Map<string, string>(Object.values(photos).map((ph) => [ph.src, ph.alt]));
const dayOf = (src: string) => Number(src.match(/conf-day(\d)/)?.[1]) || undefined;

export const gallerySlides: GallerySlide[] = (() => {
  const highlights = galleryPhotos.map((ph) => ({ ...ph, day: dayOf(ph.src) }));
  const seen = new Set(highlights.map((s) => s.src));
  const rest = manifest
    .filter((m) => !seen.has(m.src))
    .map((m) => ({
      src: m.src,
      w: m.w,
      h: m.h,
      day: m.day,
      alt: knownAlt.get(m.src) ?? `TASA National Conference — day ${m.day}`,
    }));
  return [...highlights, ...rest];
})();
